import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    t = int(input_data[idx])
    idx += 1

    results = []

    for _ in range(t):
        m = int(input_data[idx])
        k = int(input_data[idx+1])
        idx += 2

        a = []
        for i in range(k):
            a.append(int(input_data[idx]))
            idx += 1

        max_count = 0
        total_nonzero = 0
        for x in a:
            if x > max_count:
                max_count = x
            if x > 0:
                total_nonzero += 1

        n = max(max_count, total_nonzero)
        if n == 0:
            n = 1

        matrix = [[0] * n for _ in range(n)]

        counts = list(a)
        used = [False] * (k + 1)
        num_used = 0

        for c in range(n):
            r = c % n
            diag = (c + r) % 2

            if num_used < k:
                while num_used < k:
                    val = num_used + 1
                    if counts[val - 1] > 0:
                        used[val] = True
                        break
                    num_used += 1

                if num_used < k:
                    val = num_used + 1
                else:
                    val = 0

            if val != 0:
                matrix[r][c] = val
                counts[val - 1] -= 1
                if counts[val - 1] == 0:
                    used[val] = False

        res_lines = [str(n)]
        for row in matrix:
            res_lines.append(" ".join(map(str, row)))
        results.append("\n".join(res_lines))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
